sqlQueries:
SELECT customer_status__c, is_active__c, count(*) FROM accounts GROUP BY 1,2 ORDER BY 3 DESC;
SELECT max(month), min(month) FROM product_usage_monthly;

SELECT count(*) FROM accounts a
WHERE a.customer_status__c = 'Active'
AND NOT EXISTS (
  SELECT 1 FROM product_usage_monthly p
  WHERE p.account_id = a.id
    AND p.month = '2026-08-01'
    AND p.active_users > 0
);

SELECT count(*) FROM accounts a
JOIN product_usage_monthly p ON p.account_id = a.id AND p.month='2026-08-01'
WHERE a.customer_status__c='Active' AND p.active_users = 0;

SELECT count(*) FROM accounts a
WHERE a.customer_status__c='Active'
AND NOT EXISTS (SELECT 1 FROM product_usage_monthly p WHERE p.account_id=a.id AND p.month='2026-08-01');
